package com.opensocket.aievent.core.iam.api.response;import com.opensocket.aievent.core.iam.organization.domain.Tenant;import java.time.Instant;
public record TenantResponse(String tenantId,String tenantCode,String tenantName,String legalName,String status,String timezone,String locale,String dataRegion,Instant createdAt,Instant updatedAt,long version){public static TenantResponse from(Tenant t){return new TenantResponse(t.tenantId().value(),t.tenantCode(),t.tenantName(),t.legalName(),t.status().name(),t.defaultTimezone().getId(),t.defaultLocale().toLanguageTag(),t.dataRegion(),t.createdAt(),t.updatedAt(),t.version());}}
